            Questionnaire(
              questionnaireJson = q,
              onSubmit = { getResponse ->
                lifecycleScope.launch {
                  try {
                    saveVisit(this@VisitFormActivity, patientId, getResponse())
                    finish()
                  } catch (e: CancellationException) {
                    // validation failed; the form shows the errors
                  }
                }
              },
              onCancel = { finish() },
            )
          } ?: Text("Loading form…")
        }
      }
    }
  }
}
